&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:300,&amp;quot;335559991&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Rightmove’s Cloud Foundations team delivers the secure, reliable,&amp;nbsp;scalable&amp;nbsp;and cost‑optimised&amp;nbsp;platform foundations used by hundreds of engineers and dozens of mission‑critical services. As we ensure safe, low friction delivery of core services and&amp;nbsp;operate&amp;nbsp;at scale, the Engineering Manager will lead a team providing cloud&amp;nbsp;platforms and&amp;nbsp;infrastructure, cloud security, governance, automation, and operational excellence.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:210,&amp;quot;335559739&amp;quot;:210,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
